#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> infected(n);
    for (auto &v : infected) cin >> v;
    vector<vector<int>> adj(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        adj[a - 1].push_back(b - 1);
        adj[b - 1].push_back(a - 1);
    }
    // Try every node as the deleted one and count what the remaining sources reach.
    int best = n + 1, answer = 0;
    for (int removed = 0; removed < n; removed++) {
        vector<char> seen(n);
        seen[removed] = 1;
        vector<int> q;
        for (int i = 0; i < n; i++)
            if (infected[i] && i != removed) seen[i] = 1, q.push_back(i);
        for (size_t h = 0; h < q.size(); h++)
            for (int v : adj[q[h]])
                if (!seen[v]) seen[v] = 1, q.push_back(v);
        if ((int)q.size() < best) best = q.size(), answer = removed;
    }
    cout << answer + 1 << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        int[] infected = new int[n];
        for (int i = 0; i < n; i++) infected[i] = nextInt();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < m; i++) {
            int a = nextInt() - 1, b = nextInt() - 1;
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
        int best = n + 1, answer = 0;
        int[] q = new int[n];
        for (int removed = 0; removed < n; removed++) {
            boolean[] seen = new boolean[n];
            seen[removed] = true;
            int tail = 0;
            for (int i = 0; i < n; i++)
                if (infected[i] == 1 && i != removed) {
                    seen[i] = true;
                    q[tail++] = i;
                }
            for (int h = 0; h < tail; h++)
                for (int v : adj.get(q[h]))
                    if (!seen[v]) {
                        seen[v] = true;
                        q[tail++] = v;
                    }
            if (tail < best) {
                best = tail;
                answer = removed;
            }
        }
        System.out.println(answer + 1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	infected := make([]int, n)
	for i := range infected {
		infected[i] = nextInt()
	}
	adj := make([][]int, n)
	for i := 0; i < m; i++ {
		a, b := nextInt()-1, nextInt()-1
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
	}
	best, answer := n+1, 0
	for removed := 0; removed < n; removed++ {
		seen := make([]bool, n)
		seen[removed] = true
		q := []int{}
		for i, v := range infected {
			if v == 1 && i != removed {
				seen[i] = true
				q = append(q, i)
			}
		}
		for h := 0; h < len(q); h++ {
			for _, v := range adj[q[h]] {
				if !seen[v] {
					seen[v] = true
					q = append(q, v)
				}
			}
		}
		if len(q) < best {
			best, answer = len(q), removed
		}
	}
	fmt.Println(answer + 1)
}
